// The C++ clustering must give the Python detector's clusters on the same points
// (golden_cluster.txt, generated by tools/golden/gen_golden.py).
#include <gtest/gtest.h>

#include <cmath>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>

#include "buggy_core/perception/obstacle_clustering.hpp"

TEST(ObstacleClustering, MatchesPythonReference)
{
  std::ifstream f(std::string(GOLDEN_DIR) + "/golden_cluster.txt");
  ASSERT_TRUE(f.good()) << "run tools/golden/gen_golden.py first";
  std::vector<buggy_core::Point3> pts;
  buggy_core::Polyline corridor;
  std::vector<std::array<double, 6>> expect;
  std::string line;
  while (std::getline(f, line)) {
    if (line.empty() || line[0] == '#') {continue;}
    std::istringstream ss(line);
    char tag;
    ss >> tag;
    if (tag == 'P') {
      buggy_core::Point3 p;
      ss >> p.x >> p.y >> p.z;
      pts.push_back(p);
    } else if (tag == 'C') {
      double x, y;
      ss >> x >> y;
      corridor.push_back({x, y});
    } else if (tag == 'K') {
      std::array<double, 6> k;
      for (auto & v : k) {ss >> v;}
      expect.push_back(k);
    }
  }
  ASSERT_FALSE(pts.empty());
  buggy_core::DetectorParams prm;      // defaults == the Python defaults
  const auto got = buggy_core::detect_clusters(pts, corridor, prm);
  ASSERT_EQ(got.size(), expect.size());
  for (size_t i = 0; i < got.size(); ++i) {
    EXPECT_NEAR(got[i].cx, expect[i][0], 1e-9) << "cluster " << i;
    EXPECT_NEAR(got[i].cy, expect[i][1], 1e-9);
    EXPECT_NEAR(got[i].lx, expect[i][2], 1e-9);
    EXPECT_NEAR(got[i].ly, expect[i][3], 1e-9);
    EXPECT_NEAR(got[i].h, expect[i][4], 1e-9);
    EXPECT_EQ(got[i].n, static_cast<int>(expect[i][5]));
  }
}

TEST(ObstacleClustering, CorridorFallsBackToStraightAhead)
{
  const auto c = buggy_core::corridor_ahead({}, 0, 0, 0, 25.0);
  ASSERT_EQ(c.size(), 50u);
  EXPECT_DOUBLE_EQ(c.front()[0], 0.0);
  EXPECT_DOUBLE_EQ(c.back()[0], 24.5);
}

TEST(ObstacleClustering, HeightAndRangeFilter)
{
  buggy_core::DetectorParams prm;
  // sensor frame: z = -1.0 is ground (sensor 1 m up); +0.5 => 0.5 m above ground; far point dropped
  std::vector<buggy_core::Point3> s = {{5, 0, -1.0}, {5, 0, -0.5}, {5, 0, 1.5}, {40, 0, -0.5},
    {NAN, 0, 0}};
  const auto b = buggy_core::to_base_frame(s, prm);
  ASSERT_EQ(b.size(), 1u);
  EXPECT_NEAR(b[0].x, 5 + 1.73, 1e-12);
  EXPECT_NEAR(b[0].z, 0.5, 1e-12);
}
